const TOPOLOGY_MAP = {
  "twin balanced pins": 2,
  "triad focal points": 3,
  "quad pinch array": 4,
  "pentagonal vise cage": 5,
  "hexagonal crushing ring": 6,
  "chaotic eight-point cluster": 8
};

const FRACTURE_MAP = {
  "flawless clear cast": 0,
  "incipient craze lines": 0.05,
  "transient stress fractures": 0.15,
  "branching shock wakes": 0.3,
  "violent acoustic crackle": 0.6,
  "catastrophic shatter cascade": 1.0
};

const DENSITY_MAP = {
  "broad laminar fringes": 15,
  "gentle ripple bands": 25,
  "tight topographic terraces": 40,
  "compressed optical rings": 60,
  "hairline interference comb": 90,
  "hyper-dense diffraction mesh": 140
};

const ROTATION_MAP = {
  "orthogonal zero null": 0,
  "fifteen degree tilt": 15,
  "thirty degree shear": 30,
  "forty-five degree maximum": 45,
  "sixty degree inverted phase": 60,
  "counter-rotating twin filter": -1
};

const PALETTE_MAP = {
  "newton first order": 0,
  "birefringent solar spectrum": 1,
  "high-order pastels": 2,
  "saturated neon isochromes": 3,
  "deep ultraviolet magenta": 4,
  "anomalous metallic dispersion": 5
};

let anchors = [];
let crackles = [];
let cols = 100, rows = 100;
let res = 8; 
let field = [];
let os;

p.setup = function() {
  p.createCanvas(800, 800);
  os = p.createGraphics(100, 100);
  os.pixelDensity(1);
  os.colorMode(p.HSB, 360, 100, 100, 255);
  p.colorMode(p.HSB, 360, 100, 100, 255);

  for (let i = 0; i < 8; i++) {
    anchors.push({ 
      phase1: p.random(1000), 
      phase2: p.random(1000), 
      speed: p.random(0.01, 0.03)
    });
  }
  for (let i = 0; i < 50; i++) {
    crackles.push({ x1: 0, y1: 0, x2: 0, y2: 0, life: 0, maxLife: 10 });
  }
  for (let i = 0; i < cols * rows; i++) {
    field.push(0);
  }
};

p.draw = function() {
  const topVal = p.getSynthVar("anchor_topology") || "twin balanced pins";
  const fracVal = p.getSynthVar("shear_fracture") || "flawless clear cast";
  const denVal = p.getSynthVar("fringe_density") || "broad laminar fringes";
  const rotVal = p.getSynthVar("analyzer_rotation") || "orthogonal zero null";
  const palVal = p.getSynthVar("chromatic_retardation") || "newton first order";

  const numAnchors = TOPOLOGY_MAP[topVal];
  const fracChance = FRACTURE_MAP[fracVal];
  const density = DENSITY_MAP[denVal];
  let rotation = ROTATION_MAP[rotVal];
  const palette = PALETTE_MAP[palVal];

  if (rotation === -1) {
    rotation = (p.frameCount * 0.5) % 360;
  }

  const rotRad = p.radians(rotation);
  const time = p.frameCount;

  let currentAnchors = [];
  for (let i = 0; i < numAnchors; i++) {
    let a = anchors[i];
    let cx = 50 + Math.cos(a.phase1 + time * a.speed) * 35;
    let cy = 50 + Math.sin(a.phase2 + time * a.speed) * 35;
    currentAnchors.push({ x: cx, y: cy });
  }

  if (fracChance > 0 && p.random(1) < fracChance) {
    for (let i = 0; i < currentAnchors.length; i++) {
      for (let j = i + 1; j < currentAnchors.length; j++) {
        let dx = currentAnchors[i].x - currentAnchors[j].x;
        let dy = currentAnchors[i].y - currentAnchors[j].y;
        if (dx*dx + dy*dy < 400) { 
          spawnCrackle(
            (currentAnchors[i].x + currentAnchors[j].x) * 0.5 * res, 
            (currentAnchors[i].y + currentAnchors[j].y) * 0.5 * res,
            fracChance
          );
        }
      }
    }
  }

  os.loadPixels();
  let idx = 0;
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      let stress = 0.5; // ambient baseline
      for (let i = 0; i < numAnchors; i++) {
        let dx = x - currentAnchors[i].x;
        let dy = y - currentAnchors[i].y;
        let dSq = dx * dx + dy * dy + 10; 
        stress += 50 / Math.sqrt(dSq);
      }

      let phaseShift = stress + Math.sin(rotRad + x*0.02) * 2;
      field[idx] = phaseShift;

      let v = (phaseShift * density) % 100;
      let h, s, b;

      switch(palette) {
        case 0: h = v * 3.6; s = 80; b = 90 - Math.abs(50 - v); break;
        case 1: h = (v * 10.8) % 360; s = 100; b = 100; break;
        case 2: h = (v * 7.2) % 360; s = 40; b = 95; break;
        case 3: h = (v * 3.6 + 180) % 360; s = 100; b = v > 50 ? 100 : 30; break;
        case 4: h = 280 + (v * 0.6); s = 90; b = (Math.sin(v * 0.1) * 50) + 50; break;
        case 5: h = 40; s = (v * 2) % 100; b = (Math.cos(v * 0.1) * 50) + 50; break;
      }

      let pixIdx = (x + y * cols) * 4;
      let rgb = hsbToRgb(h, s, b);
      os.pixels[pixIdx] = rgb[0];
      os.pixels[pixIdx+1] = rgb[1];
      os.pixels[pixIdx+2] = rgb[2];
      os.pixels[pixIdx+3] = 255;
      idx++;
    }
  }
  os.updatePixels();

  p.noSmooth();
  p.image(os, 0, 0, 800, 800);
  p.smooth();

  p.stroke(0, 0, 20, 100);
  p.strokeWeight(1);
  p.beginShape(p.LINES);

  const step = 800 / cols;
  for (let y = 0; y < rows - 1; y++) {
    for (let x = 0; x < cols - 1; x++) {
      let i = x + y * cols;
      let v0 = (field[i] * density) % 10;
      let v1 = (field[i+1] * density) % 10;
      let v2 = (field[i+cols+1] * density) % 10;
      let v3 = (field[i+cols] * density) % 10;

      let state = 0;
      if (v0 > 5) state |= 1;
      if (v1 > 5) state |= 2;
      if (v2 > 5) state |= 4;
      if (v3 > 5) state |= 8;

      let px = x * step, py = y * step;
      let half = step * 0.5;

      switch (state) {
        case 1: case 14: p.vertex(px, py + half); p.vertex(px + half, py); break;
        case 2: case 13: p.vertex(px + half, py); p.vertex(px + step, py + half); break;
        case 4: case 11: p.vertex(px + step, py + half); p.vertex(px + half, py + step); break;
        case 8: case 7: p.vertex(px + half, py + step); p.vertex(px, py + half); break;
        case 3: case 12: p.vertex(px, py + half); p.vertex(px + step, py + half); break;
        case 6: case 9: p.vertex(px + half, py); p.vertex(px + half, py + step); break;
        case 5: p.vertex(px, py + half); p.vertex(px + half, py); p.vertex(px + half, py + step); p.vertex(px + step, py + half); break;
        case 10: p.vertex(px + half, py); p.vertex(px + step, py + half); p.vertex(px, py + half); p.vertex(px + half, py + step); break;
      }
    }
  }
  p.endShape();

  p.strokeWeight(2);
  for (let c of crackles) {
    if (c.life > 0) {
      let alpha = p.map(c.life, 0, c.maxLife, 0, 255);
      p.stroke(0, 0, 100, alpha);
      p.line(c.x1, c.y1, c.x2, c.y2);
      c.life--;
    }
  }
};

function spawnCrackle(cx, cy, intensity) {
  for (let c of crackles) {
    if (c.life <= 0) {
      c.x1 = cx + (Math.random() - 0.5) * 40;
      c.y1 = cy + (Math.random() - 0.5) * 40;
      c.x2 = c.x1 + (Math.random() - 0.5) * 80 * intensity;
      c.y2 = c.y1 + (Math.random() - 0.5) * 80 * intensity;
      c.life = Math.floor(Math.random() * 15) + 5;
      c.maxLife = c.life;
      break;
    }
  }
}

function hsbToRgb(h, s, b) {
  s /= 100;
  b /= 100;
  const k = (n) => (n + h / 60) % 6;
  const f = (n) => b * (1 - s * Math.max(0, Math.min(k(n), 4 - k(n), 1)));
  return [255 * f(5), 255 * f(3), 255 * f(1)];
}
